package com.moapan.site;
import com.moapan.*;
import com.moapan.source.SafeFetch;
import com.moapan.security.Limits;
import jakarta.validation.constraints.*;
import org.springframework.stereotype.Service;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.transaction.annotation.Transactional;
import java.util.*;
import java.time.*;

@Service @PreAuthorize("hasRole('ADMIN')")
public class CatalogService {
    public record SiteInput(@NotBlank @Size(max=160)String name,@NotBlank @Size(max=2048)String homepageUrl,@Size(max=1000)String description,@Size(max=2000)String adminNote,Long version){}
    public record SourceInput(@NotBlank @Size(max=160)String label,@NotBlank String type,@NotBlank @Size(max=2048)String endpointUrl,@Size(max=20)String language,Integer intervalSeconds,boolean enabled,String rightsStatus,boolean allowMetadata,boolean allowDisplay,boolean allowSummary,boolean allowBody,boolean allowStore,boolean allowTranslation,boolean allowImage,boolean allowExternalAi,String termsUrl,LocalDate termsCheckedOn,@Size(max=2000)String reviewNote,Map<String,String> jsonMapping,String secretRef,Long version){}
    @org.springframework.beans.factory.annotation.Value("${moapan.source-min-interval:300}") private int minimumInterval;
    private final CatalogRepository repo;private final SafeFetch fetch;private final Limits limits;
    public CatalogService(CatalogRepository repo,SafeFetch fetch,Limits limits){this.repo=repo;this.fetch=fetch;this.limits=limits;}
    public Object sites(String search,String state,String result,String sort,int page,int size){
        if(page<0||page>10000||size<1||size>100||search.length()>160||!Set.of("name","success").contains(sort)||!Set.of("","DRAFT","ACTIVE","PAUSED","ARCHIVED").contains(state)||!Set.of("","SUCCEEDED","FAILED").contains(result))throw new ApiError(400,"invalid_filter");
        String sql="SELECT s.*, (SELECT count(*) FROM sources x WHERE x.site_id=s.id AND x.archived_at IS NULL) AS source_count, (SELECT count(*) FROM sources x WHERE x.site_id=s.id AND x.enabled AND x.validation_status='PASSED' AND x.allow_metadata AND x.allow_display AND x.rights_status IN ('APPROVED','RESTRICTED') AND x.archived_at IS NULL) AS runnable_count, (SELECT max(f.started_at) FROM fetch_runs f JOIN sources x ON x.id=f.source_id WHERE x.site_id=s.id) AS last_attempt, (SELECT max(f.finished_at) FROM fetch_runs f JOIN sources x ON x.id=f.source_id WHERE x.site_id=s.id AND f.result IN ('SUCCEEDED','NO_CHANGE')) AS last_success, (SELECT f.result FROM fetch_runs f JOIN sources x ON x.id=f.source_id WHERE x.site_id=s.id ORDER BY f.started_at DESC LIMIT 1) AS last_result FROM sites s WHERE (s.name ILIKE :q OR s.homepage_url ILIKE :q) AND "+(state.isEmpty()?"s.status<>'ARCHIVED'":"s.status=:state")+" AND (:result='' OR EXISTS(SELECT 1 FROM sources x JOIN fetch_runs f ON f.source_id=x.id WHERE x.site_id=s.id AND f.result=:result)) ORDER BY "+(sort.equals("name")?"s.name,s.id":"last_success DESC NULLS LAST,s.id")+" LIMIT :limit OFFSET :offset";
        return repo.db().sql(sql).param("q","%"+search.replace("%","\\%").replace("_","\\_")+"%").param("state",state).param("result",result).param("limit",size).param("offset",page*size).query().listOfRows();
    }
    public Object site(UUID id){return repo.site(id,false);}
    public Object source(UUID id){var detail=new java.util.LinkedHashMap<String,Object>(repo.source(id,false));detail.put("publishedArticleCount",repo.db().sql("SELECT count(*) FROM articles WHERE source_id=:id AND public").param("id",id).query(Long.class).single());return detail;}
    public Object sources(UUID site){repo.site(site,false);return repo.db().sql("SELECT * FROM sources WHERE site_id=:id ORDER BY label,id").param("id",site).query().listOfRows();}
    @Transactional public Object createSite(SiteInput input,UUID actor){UUID id=UUID.randomUUID();String url=SafeFetch.canonical(input.homepageUrl());repo.db().sql("INSERT INTO sites(id,name,homepage_url,normalized_homepage_url,description,admin_note) VALUES(:id,:name,:url,:url,:description,:note)").param("id",id).param("name",input.name()).param("url",url).param("description",safe(input.description())).param("note",safe(input.adminNote())).update();audit(actor,"site_create",id);return repo.site(id,false);}
    @Transactional public Object updateSite(UUID id,SiteInput input,UUID actor){var site=repo.site(id,true);version(site,input.version());String url=SafeFetch.canonical(input.homepageUrl());repo.db().sql("UPDATE sites SET name=:name,homepage_url=:url,normalized_homepage_url=:url,description=:description,admin_note=:note,version=version+1,updated_at=now() WHERE id=:id").param("id",id).param("name",input.name()).param("url",url).param("description",safe(input.description())).param("note",safe(input.adminNote())).update();cancelSite(id);audit(actor,"site_update",id);return repo.site(id,false);}
    @Transactional public Object state(UUID id,String next,UUID actor){var site=repo.site(id,true);
        if(next.equals("ACTIVE")){
            if(site.get("status").equals("ARCHIVED"))throw new ApiError(409,"restore_first");
            int n=repo.db().sql("SELECT count(*) FROM sources WHERE site_id=:id AND enabled AND validation_status='PASSED' AND allow_metadata AND allow_display AND rights_status IN ('APPROVED','RESTRICTED') AND archived_at IS NULL").param("id",id).query(Integer.class).single();if(n==0)throw new ApiError(409,"no_runnable_sources");
        }
        repo.db().sql("UPDATE sites SET status=:s,version=version+1,updated_at=now(),archived_at=CASE WHEN :s='ARCHIVED' THEN now() ELSE NULL END WHERE id=:id").param("s",next).param("id",id).update();cancelSite(id);
        repo.db().sql("UPDATE sources SET next_run_at=now()+make_interval(secs=>interval_seconds)"+(site.get("status").equals("ARCHIVED")?",enabled=false,validation_status='NOT_TESTED',rights_status='UNREVIEWED',version=version+1":"")+" WHERE site_id=:id").param("id",id).update();audit(actor,"site_"+next.toLowerCase(Locale.ROOT),id);return repo.site(id,false);
    }
    @Transactional public Object createSource(UUID siteId,SourceInput input,UUID actor){repo.site(siteId,true);UUID id=UUID.randomUUID();validate(input);String url=SafeFetch.canonical(input.endpointUrl());repo.db().sql("INSERT INTO sources(id,site_id,label,type,endpoint_url,normalized_endpoint_url,language,interval_seconds) VALUES(:id,:site,:label,:type,:url,:url,:language,:interval)").param("id",id).param("site",siteId).param("label",input.label()).param("type",input.type()).param("url",url).param("language",input.language()==null?"en":input.language()).param("interval",input.intervalSeconds()==null?Math.max(900,minimumInterval):input.intervalSeconds()).update();audit(actor,"source_create",id);return repo.source(id,false);}
    @Transactional public Object updateSource(UUID id,SourceInput input,UUID actor){var original=repo.source(id,false);repo.site((UUID)original.get("site_id"),true);var source=repo.source(id,true);version(source,input.version());validate(input);String url=SafeFetch.canonical(input.endpointUrl());boolean reset=!url.equals(source.get("endpoint_url"))||!input.type().equals(source.get("type"))||!safe(input.secretRef()).equals(safe((String)source.get("secret_ref")));
        if(input.enabled()&&(!source.get("validation_status").equals("PASSED")||reset||source.get("archived_at")!=null))throw new ApiError(409,"source_not_validated");
        if(input.enabled()&&(!input.allowMetadata()||!input.allowDisplay()||!Set.of("APPROVED","RESTRICTED").contains(input.rightsStatus())))throw new ApiError(409,"rights_required");
        repo.db().sql("UPDATE sources SET label=:label,type=:type,endpoint_url=:url,normalized_endpoint_url=:url,language=:language,interval_seconds=:interval,enabled=:enabled,rights_status=:rights,allow_metadata=:metadata,allow_display=:display,allow_summary=:summary,allow_body=:body,allow_store=:store,allow_translation=:translation,allow_image=:image,allow_external_ai=:ai,terms_url=:terms,terms_checked_on=:checked,review_note=:note,json_mapping=CAST(:mapping AS jsonb),secret_ref=:secret,validation_status=CASE WHEN :reset THEN 'NOT_TESTED' ELSE validation_status END,validated_at=CASE WHEN :reset THEN NULL ELSE validated_at END,next_run_at=now()+make_interval(secs=>:interval),version=version+1 WHERE id=:id")
            .param("id",id).param("label",input.label()).param("type",input.type()).param("url",url).param("language",input.language()==null?"en":input.language()).param("interval",input.intervalSeconds()==null?Math.max(900,minimumInterval):input.intervalSeconds()).param("enabled",input.enabled()&&!reset).param("rights",reset?"UNREVIEWED":input.rightsStatus()==null?"UNREVIEWED":input.rightsStatus()).param("metadata",input.allowMetadata()&&!reset).param("display",input.allowDisplay()&&!reset).param("summary",input.allowSummary()&&!reset).param("body",false).param("store",false).param("translation",false).param("image",false).param("ai",false).param("terms",input.termsUrl()).param("checked",input.termsCheckedOn()).param("note",reset?"Endpoint changed: review required":safe(input.reviewNote())).param("mapping",tools.jackson.databind.json.JsonMapper.builder().build().writeValueAsString(input.jsonMapping()==null?Map.of():input.jsonMapping())).param("secret",input.secretRef()).param("reset",reset).update();
        cancelSource(id);if(reset||!input.allowDisplay()||!Set.of("APPROVED","RESTRICTED").contains(input.rightsStatus()==null?"UNREVIEWED":input.rightsStatus()))repo.db().sql("UPDATE articles SET public=false WHERE source_id=:id").param("id",id).update();audit(actor,reset?"source_endpoint_reset":"source_update",id);return repo.source(id,false);
    }
    @Transactional public Object archiveSource(UUID id,boolean archive,UUID actor){var s=repo.source(id,false);repo.site((UUID)s.get("site_id"),true);repo.source(id,true);repo.db().sql("UPDATE sources SET enabled=false,archived_at="+(archive?"now()":"NULL")+",validation_status='NOT_TESTED',rights_status="+(archive?"rights_status":"'UNREVIEWED'")+",version=version+1 WHERE id=:id").param("id",id).update();cancelSource(id);audit(actor,archive?"source_archive":"source_restore",id);return repo.source(id,false);}
    public Object preview(UUID id,boolean validateOnly,UUID actor){limits.auth("source_check_global",60,60);var s=repo.source(id,false);if(!(boolean)s.get("allow_metadata")||!Set.of("APPROVED","RESTRICTED").contains(s.get("rights_status")))throw new ApiError(403,"metadata_rights_required");
        try {var requestSource=new java.util.LinkedHashMap<String,Object>(s);requestSource.remove("etag");requestSource.remove("last_modified");var result=fetch.read(requestSource);if(validateOnly){recordValidation(id,((Number)s.get("version")).longValue(),true);audit(actor,"source_validate",id);return Map.of("status","PASSED");}return Map.of("notice","미리보기이며 기사로 저장·공개되지 않았습니다.","items",result.items().stream().limit(5).map(i->Map.of("title",i.title(),"originalUrl",i.url(),"publishedAt",i.publishedAt()==null?"":i.publishedAt().toString(),"description",(boolean)s.get("allow_display")?i.description():"")).toList());
        }catch(SafeFetch.FetchFailure e){if(validateOnly)recordValidation(id,((Number)s.get("version")).longValue(),false);throw new ApiError(502,"source_retryable");}catch(ApiError e){if(validateOnly)recordValidation(id,((Number)s.get("version")).longValue(),false);throw e;}
    }
    private void recordValidation(UUID id,long version,boolean ok){int n=repo.db().sql("UPDATE sources SET validation_status=:s,validated_at=now() WHERE id=:id AND version=:v").param("s",ok?"PASSED":"FAILED").param("id",id).param("v",version).update();if(n!=1)throw new ApiError(409,"source_changed");}
    @Transactional public Object collect(UUID id,UUID actor){var s=repo.source(id,false);var site=repo.site((UUID)s.get("site_id"),true);s=repo.source(id,true);runnable(site,s);var live=repo.db().sql("SELECT id,status FROM content_jobs WHERE source_id=:id AND status IN ('QUEUED','RUNNING')").param("id",id).query().listOfRows();if(!live.isEmpty())return live.getFirst();UUID job=UUID.randomUUID();repo.db().sql("INSERT INTO content_jobs(id,source_id,status,site_version,source_version,available_at) VALUES(:job,:id,'QUEUED',:sv,:v,GREATEST(now(),COALESCE((SELECT retry_after FROM sources WHERE id=:id),now())))").param("job",job).param("id",id).param("sv",site.get("version")).param("v",s.get("version")).update();audit(actor,"source_collect",id);return Map.of("id",job,"status","QUEUED");}
    public Object runs(UUID id){return repo.db().sql("SELECT * FROM fetch_runs WHERE source_id=:id ORDER BY started_at DESC LIMIT 50").param("id",id).query().listOfRows();}
    public Object job(UUID id){return repo.db().sql("SELECT id,source_id,status,attempts,created_at,finished_at,error_code FROM content_jobs WHERE id=:id").param("id",id).query().listOfRows().stream().findFirst().orElseThrow(()->new ApiError(404,"job_not_found"));}
    public Object heartbeat(){return repo.db().sql("SELECT * FROM worker_status").query().listOfRows();}
    public static void runnable(Map<String,Object>site,Map<String,Object>s){if(!site.get("status").equals("ACTIVE")||!(boolean)s.get("enabled")||s.get("archived_at")!=null||!s.get("validation_status").equals("PASSED")||!(boolean)s.get("allow_metadata")||!(boolean)s.get("allow_display")||!Set.of("APPROVED","RESTRICTED").contains(s.get("rights_status")))throw new ApiError(409,"source_not_runnable");}
    private void validate(SourceInput i){if(!Set.of("RSS","ATOM","JSON_API").contains(i.type())||i.intervalSeconds()!=null&&(i.intervalSeconds()<Math.max(300,minimumInterval)||i.intervalSeconds()>86400))throw new ApiError(400,"invalid_source");if(i.allowBody()||i.allowStore()||i.allowTranslation()||i.allowImage()||i.allowExternalAi())throw new ApiError(400,"unsupported_action");if(i.rightsStatus()!=null&&!Set.of("UNREVIEWED","APPROVED","RESTRICTED","DISABLED").contains(i.rightsStatus()))throw new ApiError(400,"invalid_rights");if(i.rightsStatus()!=null&&Set.of("APPROVED","RESTRICTED").contains(i.rightsStatus())&&(i.termsUrl()==null||i.termsCheckedOn()==null||i.termsCheckedOn().isAfter(LocalDate.now())))throw new ApiError(400,"rights_evidence_required");if(i.termsUrl()!=null)SafeFetch.canonical(i.termsUrl());if(i.jsonMapping()!=null)for(var e:i.jsonMapping().entrySet())if(!Set.of("items","id","title","url","publishedAt","description").contains(e.getKey())||!e.getValue().matches("[A-Za-z0-9_.]{1,100}"))throw new ApiError(400,"invalid_mapping");if(i.secretRef()!=null&&!i.secretRef().matches("MOAPAN_SOURCE_[A-Z0-9_]{1,50}"))throw new ApiError(400,"invalid_secret_reference");}
    private void cancelSite(UUID id){repo.db().sql("UPDATE content_jobs SET status='CANCELLED',finished_at=now() WHERE source_id IN (SELECT id FROM sources WHERE site_id=:id) AND status IN ('QUEUED','RUNNING')").param("id",id).update();}
    private void cancelSource(UUID id){repo.db().sql("UPDATE content_jobs SET status='CANCELLED',finished_at=now() WHERE source_id=:id AND status IN ('QUEUED','RUNNING')").param("id",id).update();}
    public void audit(UUID actor,String action,UUID target){repo.db().sql("INSERT INTO admin_actions(id,admin_id,action,target_id) VALUES(:id,:actor,:action,:target)").param("id",UUID.randomUUID()).param("actor",actor).param("action",action).param("target",target).update();}
    private static void version(Map<String,Object> row,Long version){if(version==null||((Number)row.get("version")).longValue()!=version)throw new ApiError(409,"version_conflict");}
    private static String safe(String value){return value==null?"":value;}
}
